import json
from pathlib import Path
r=Path('benchmarks/dense500');aid='PMC12714400.1';s=json.load(open(r/'sources'/f'{aid}.json'));sg={x['segment_id']:x['text'] for x in s['segments']};assets=json.load(open(r/'figure-assets'/f'{aid}.json'))
def ev(sid,q):assert q in sg[sid];return dict(segment_id=sid,quote=q)
def tag(v,sid,q,doc=None):return dict(value=v,as_documented=doc,basis='caption',visual_cue=None,evidence=[ev(sid,q)],certainty='clear')
D=[('FIG1','b00017','MRCP image showing a thick-walled gallbladder containing a 2 cm calculus, with the extent of the subcapsular biloma.','Grayscale abdominal MRCP image annotated with two red arrows.','A single frontal abdominal section on a black field shows a broad dark organ at image left with a bright crescent-shaped region along its upper margin. A red arrow rises from left center toward that crescent. A second red arrow runs from lower center toward a smaller pale elongated structure containing a dark circular focus at its left end. Bright rounded fluid-like regions and dark bowel-like profiles lie to the right and lower portions of the section. No panel letter, caliper, scale bar, numerical measurement, sequence name or date is visible.',['Two thick red arrows highlight separate structures.','Upper arrow points to a bright crescent along a broad dark organ.','Lower arrow points to an elongated pale structure with a dark circular focus.'],'The authors identify gallbladder wall thickening, a2cmcalculus and subcapsular-biloma extent; the stated dimension comes from caption/workup, not pixel measurement.'),('FIG2','b00018','MRCP image demonstrating the focal fundal perforation of the gallbladder, confirming the site of perforation.','Grayscale abdominal MRCP image with a red arrow near the gallbladder region.','A single frontal grayscale abdominal section shows a broad dark organ at image left with a bright crescent above it. A thick red arrow from the lower-left border points to a small bright region just left of a rounded bright focus in a pale horizontal structure. Several rounded bright regions, dark bowel-like profiles and surrounding soft tissues occupy the central and lower abdomen. An L side marker is visible near the right edge. No panel letters, lesion calipers, numerical measurements, scale bar or acquisition sequence labels are visible.',['One thick red arrow points toward a small bright region near a rounded bright focus.','Bright crescent lies above the broad dark organ at image left.','L side marker appears at the right margin.'],'The authors identify focal gallbladder-fundal perforation; image appearance alone does not establish perforation or a new diagnosis.')]
rows=[]
for fid,sid,q,general,detail,pixels,meaning in D:
 ce=ev(sid,q);ae=ev('b00007','MRCP demonstrated a thick-walled gallbladder containing multiple calculi, the largest measuring 2 cm (Figure 1).') if fid=='FIG1' else ev('b00007','Appearances suggested a focal fundal perforation (Figure 2), with fluid extending beneath the hepatic capsule to form a 10 × 4 cm subcapsular collection.')
 limits=['No readable measurement/caliper supports a pixel-derived dimension.','Sequence, contrast administration and acquisition date are not reported by the supplied image/caption.','Author-reported anatomy and diagnosis kept distinct from visible grayscale patterns.']
 p=dict(panel=None,general_description=general,detailed_description=detail,image_kind='medical_imaging',has_chart=False,charts=[],imaging_modalities=[tag('mri',sid,'MRCP',doc='MRCP')],imaging_submodalities=[tag('magnetic_resonance_cholangiopancreatography',sid,'Magnetic resonance cholangiopancreatography',doc='Magnetic resonance cholangiopancreatography')],medical_domains=[tag('radiology',sid,'MRCP',doc='MRCP')],body_parts=[tag('gallbladder',sid,'gallbladder',doc='gallbladder')]+([tag('hepatic subcapsular space',sid,'subcapsular biloma',doc='subcapsular biloma')] if fid=='FIG1' else [tag('gallbladder fundus',sid,'focal fundal perforation of the gallbladder',doc='focal fundal perforation of the gallbladder')]),mentioned_categories=[],pixel_observations=pixels,caption_claims=[tag(q,sid,q,doc=q)],clinical_significance=[dict(statement=meaning.replace('a2cmcalculus','a 2 cm calculus'),role='diagnostic_evidence',clinical_fact_status='unreviewed_annotation',basis='caption',visual_cue=None,evidence=[ce],certainty='clear')],diagram_relations=[],limitations=limits)
 ar=next(x for x in assets['figures'] if x['figure_id']==fid)
 rows.append(dict(figure_id=fid,status='inspected',assets=[dict(url=x['url'],sha256=x['sha256']) for x in ar['assets']],analysis=dict(visual=dict(figure_id=fid,general_description=general,detailed_description=detail,panels=[p],limitations=limits),attribution=dict(figure_id=fid,assignments=[dict(panel=None,patient_ids=['p1'],scope='individual',subject='patient',evidence=[ce,ae],rationale='Both figure callouts occur in the sole original patient MRCP workup; ownership follows case/caption evidence, not resemblance.')],limitations=[])),limitations=limits))
(r/'visual-submissions'/f'{aid}.json').write_text(json.dumps(dict(format='dense-figure-reference/1',article_id=aid,source_text_sha256=s['text_sha256'],figures=rows),ensure_ascii=False,indent=2)+'\n')
